import { imageManifest } from '../data/generated/imageManifest'
import { resolveImage } from '../data/images'

function set(name) {
  const sources = name.sources || {}
  const parts = []
  if (sources.avif) {
    parts.push(
      <source key="avif" type="image/avif" srcSet={sources.avif} sizes={name.sizes} />,
    )
  }
  if (sources.webp) {
    parts.push(
      <source key="webp" type="image/webp" srcSet={sources.webp} sizes={name.sizes} />,
    )
  }
  return parts
}

/**
 * Responsive image with AVIF/WebP sources generated by `npm run images`.
 * Falls back to the bundled original when a derivative is unavailable.
 */
export default function Picture({
  name,
  src,
  alt = '',
  sizes = '100vw',
  priority = false,
  className = '',
  imgClassName = '',
  width,
  height,
  ...rest
}) {
  const entry = name ? imageManifest[name] : null
  const fallback = resolveImage(src || entry?.src || name)
  const loading = priority ? 'eager' : 'lazy'

  if (!entry) {
    return (
      <img
        src={fallback}
        alt={alt}
        className={imgClassName || undefined}
        loading={loading}
        decoding="async"
        fetchPriority={priority ? 'high' : undefined}
        width={width}
        height={height}
        {...rest}
      />
    )
  }

  return (
    <picture className={className || undefined}>
      {set({ ...entry, sizes })}
      <img
        src={entry.src}
        srcSet={entry.sources.jpg}
        sizes={sizes}
        alt={alt}
        width={width ?? entry.width}
        height={height ?? entry.height}
        className={imgClassName || undefined}
        loading={loading}
        decoding="async"
        fetchPriority={priority ? 'high' : undefined}
        {...rest}
      />
    </picture>
  )
}
